{{!-- Styling parameters: class, titleClass, gridClass, cardClass, buttonClass, cardTitleClass, descriptionClass, priceClass, benefitsClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Pricing Table | Usage: {{> "components/pricing-table"}} --}}
{{#if @site.members_enabled}}
{{#unless @site.members_invite_only}}
{{#if @site.allow_self_signup}}
<section class="gh-pricing{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Membership plans">
    <h2 class="gh-pricing-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{#if title}}{{title}}{{else}}Choose your membership{{/if}}</h2>
    <div class="gh-pricing-grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
    {{#get "tiers" filter="visibility:public+active:true" include="monthly_price,yearly_price,benefits"}}
    {{#foreach tiers}}
        {{#match type "free"}}
        <article class="gh-pricing-card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}">
    <header class="gh-pricing-card__header">
        <h3 class="gh-pricing-card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}">{{name}}</h3>
        {{#if description}}<p class="gh-pricing-description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{/if}}
    </header>
    <div class="gh-pricing-card__rates"><p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">Free</p></div>
    {{#if benefits}}
    <ul class="gh-pricing-benefits{{#if ghostcnStyles.benefitsClass}} {{ghostcnStyles.benefitsClass}}{{/if}}" role="list">{{#foreach benefits}}<li>{{this}}</li>{{/foreach}}</ul>
    {{/if}}
    <div class="gh-pricing-actions">
    {{#if @member}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/account" data-portal="account">Manage account</a>
    {{else}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/signup/free" data-portal="signup/free">Join free</a>{{/if}}</div>
</article>
        {{else}}
        {{#if @site.paid_members_enabled}}
        <article class="gh-pricing-card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}} gh-pricing-card--paid">
    <header class="gh-pricing-card__header">
        <h3 class="gh-pricing-card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}">{{name}}</h3>
        {{#if description}}<p class="gh-pricing-description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{/if}}
    </header>
    <div class="gh-pricing-card__rates">
    {{#if monthly_price}}
        <p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">{{price monthly_price currency=currency}} <span>/ month</span></p>
        {{#if yearly_price}}<p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}} gh-pricing-price--alternate">{{price yearly_price currency=currency}} <span>billed yearly</span></p>{{/if}}
    {{else}}
        {{#if yearly_price}}<p class="gh-pricing-price{{#if ghostcnStyles.priceClass}} {{ghostcnStyles.priceClass}}{{/if}}">{{price yearly_price currency=currency}} <span>/ year</span></p>{{/if}}
    {{/if}}</div>
    {{#if benefits}}
    <ul class="gh-pricing-benefits{{#if ghostcnStyles.benefitsClass}} {{ghostcnStyles.benefitsClass}}{{/if}}" role="list">{{#foreach benefits}}<li>{{this}}</li>{{/foreach}}</ul>
    {{/if}}
    <div class="gh-pricing-actions">
    {{#if @member}}
        <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/account/plans" data-portal="account/plans">{{#if @member.paid}}Manage plan{{else}}Upgrade membership{{/if}}</a>
    {{else}}
        {{#if monthly_price}}
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup/{{id}}/monthly" data-portal="signup/{{id}}/monthly">Subscribe monthly</a>
            {{#if yearly_price}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} gh-pricing-alternate" href="#/portal/signup/{{id}}/yearly" data-portal="signup/{{id}}/yearly">Subscribe yearly</a>{{/if}}
        {{else}}
            {{#if yearly_price}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup/{{id}}/yearly" data-portal="signup/{{id}}/yearly">Subscribe yearly</a>{{/if}}
        {{/if}}
    {{/if}}</div>
</article>
        {{/if}}
        {{/match}}
    {{/foreach}}
    {{else}}
        <p>Membership plans are currently unavailable.</p>
    {{/get}}
    </div>
</section>
{{/if}}
{{/unless}}
{{/if}}
{{/with}}

/* ghostcn: live membership pricing */
.gh-pricing { box-sizing: border-box; min-width: 0; margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px)); font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); width: min(100% - 32px, 960px); margin-inline: auto; }
.gh-pricing *, .gh-pricing *::before, .gh-pricing *::after { box-sizing: border-box; }
.gh-pricing-title { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 0 0 var(--ghcn-section-gap, 20px); text-align: center; }
.gh-pricing-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 288px), 1fr)); gap: var(--ghcn-grid-gap, 16px); }
.gh-pricing-card { box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b); display: flex; flex-direction: column; gap: 16px; padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px)); }
.gh-pricing-card--paid { border-color: color-mix(in srgb, var(--foreground) 24%, var(--border)); }
.gh-pricing-card:only-child { width: min(100%, 440px); justify-self: center; }
.gh-pricing-card__header { display: grid; gap: 4px; }
.gh-pricing-card__rates { display: grid; gap: 4px; }
/* Follow the card's local foreground, not the page's dark/light tokens.
   A custom background must be paired with a readable foreground at the call site. */
.gh-pricing-card-title { font-size: var(--ghcn-title-card, 20px); font-weight: 650; line-height: 1.3; letter-spacing: -.025em; color: inherit; margin: 0; }
.gh-pricing-description { margin: 0; color: inherit; font-size: var(--ghcn-text-small, 14px); }
.gh-pricing-benefits { display: grid; gap: 8px; margin: 0; padding: 14px 0 0; border-block-start: 1px solid var(--border); list-style: none; color: inherit; font-size: var(--ghcn-text-small, 14px); }
.gh-pricing-benefits li { display: flex; align-items: baseline; gap: 10px; color: inherit; }
.gh-pricing-benefits li::before { content: ""; flex: 0 0 5px; height: 9px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; transform: rotate(45deg); }
.gh-pricing-price { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 0; color: inherit; font-variant-numeric: tabular-nums; }
.gh-pricing-price span { font-size: var(--ghcn-text-small, 14px); font-weight: 400; letter-spacing: normal; color: inherit; }
.gh-pricing-price--alternate { font-size: var(--ghcn-text-small, 14px); font-weight: 600; line-height: 1.5; letter-spacing: normal; }
.gh-pricing-actions { display: grid; align-content: start; gap: 4px; margin-block-start: auto; padding-block-start: 4px; }
.gh-pricing-actions:empty, .gh-pricing-card__rates:empty { display: none; }
:where(.gh-pricing-actions) .ghcn-button--outline { background: var(--background); }
.gh-pricing-alternate { justify-self: center; background: transparent; color: inherit; text-decoration: underline; text-underline-offset: 3px; }
@media (min-width: 640px) {
    :where(.gh-pricing-grid:has(.gh-pricing-price--alternate)) .gh-pricing-card__rates { min-block-size: calc(1.18 * var(--ghcn-title-section, clamp(24px, 3vw, 32px)) + 25px); align-content: start; }
    :where(.gh-pricing-grid:has(.gh-pricing-alternate)) .gh-pricing-actions { min-block-size: calc(2 * var(--ghcn-control-height, 40px) + 8px); }
}
